#!/bin/bash
fail=0
t=$(mktemp)
seed() { printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t13:00\t14:00\ty\n' > "$t"; }

seed
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel failed"; fail=1; }
[ "$out" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "cancel output: $out"; fail=1; }
! grep -q '^aoi.2026-01-05.09:00' "$t" || { echo "booking still there"; fail=1; }
grep -q '^# room' "$t" || { echo "header line removed"; fail=1; }
grep -q '^kaede.2026-01-05.13:00' "$t" || { echo "other booking removed"; fail=1; }

seed
BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 >/dev/null 2>"$t.err"; [ $? = 1 ] || { echo "not found should exit 1"; fail=1; }
[ ! -s "$t.err" ] || [ -n "$(cat "$t.err")" ] || true
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>/dev/null); [ -z "$out" ] || { echo "not found should print nothing to stdout: $out"; fail=1; }
BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>&1 >/dev/null | grep -q '^not found: aoi 2026-01-05 11:00$' || { echo "not found message should go to stderr"; fail=1; }

out=$(bash src/cancel.sh aoi 2>/dev/null); rc=$?
[ "$rc" = 2 ] || { echo "usage should exit 2, got $rc"; fail=1; }
[ -z "$out" ] || { echo "usage should print nothing to stdout"; fail=1; }
bash src/cancel.sh aoi 2>&1 >/dev/null | grep -q '^usage: cancel.sh ROOM DATE START$' || { echo "usage message should go to stderr"; fail=1; }

seed
printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t09:00\t11:00\ty\n' > "$t"
BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00 >/dev/null || { echo "cancel failed for same start in two rooms"; fail=1; }
grep -q '^kaede.2026-01-05.09:00' "$t" || { echo "other room's booking at the same start was removed"; fail=1; }
! grep -q '^aoi.2026-01-05.09:00' "$t" || { echo "booking still there (two rooms)"; fail=1; }

rm -f "$t" "$t.err"; exit $fail

